package com.sih.portal.entity; import com.sih.shared.tenant.TenantScopedEntity; import jakarta.persistence.*; import java.time.*; import lombok.*; @Entity @Getter @Setter public class Appointment extends TenantScopedEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id;@Column(nullable=false)String patientRef;@Column(nullable=false)String practitioner;@Column(nullable=false)String specialty;@Column(nullable=false)OffsetDateTime scheduledAt;@Column(nullable=false)String status="REQUESTED";}